// Why a run exists.
// Ref: #/components/schemas/DeployReason
type DeployReason string

const (
	DeployReasonDeploy    DeployReason = "deploy"
	DeployReasonRollback  DeployReason = "rollback"
	DeployReasonPromotion DeployReason = "promotion"
)

// AllValues returns all DeployReason values.
func (DeployReason) AllValues() []DeployReason {
	return []DeployReason{
		DeployReasonDeploy,
		DeployReasonRollback,
		DeployReasonPromotion,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s DeployReason) MarshalText() ([]byte, error) {
	switch s {
	case DeployReasonDeploy:
		return []byte(s), nil
	case DeployReasonRollback:
		return []byte(s), nil
	case DeployReasonPromotion:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *DeployReason) UnmarshalText(data []byte) error {
	switch DeployReason(data) {
	case DeployReasonDeploy:
		*s = DeployReasonDeploy
		return nil
	case DeployReasonRollback:
		*s = DeployReasonRollback
		return nil
	case DeployReasonPromotion:
		*s = DeployReasonPromotion
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

