// Ref: #/components/schemas/EnvType
type EnvType string

const (
	EnvTypeStandard   EnvType = "standard"
	EnvTypeProduction EnvType = "production"
	EnvTypePreview    EnvType = "preview"
)

// AllValues returns all EnvType values.
func (EnvType) AllValues() []EnvType {
	return []EnvType{
		EnvTypeStandard,
		EnvTypeProduction,
		EnvTypePreview,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s EnvType) MarshalText() ([]byte, error) {
	switch s {
	case EnvTypeStandard:
		return []byte(s), nil
	case EnvTypeProduction:
		return []byte(s), nil
	case EnvTypePreview:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *EnvType) UnmarshalText(data []byte) error {
	switch EnvType(data) {
	case EnvTypeStandard:
		*s = EnvTypeStandard
		return nil
	case EnvTypeProduction:
		*s = EnvTypeProduction
		return nil
	case EnvTypePreview:
		*s = EnvTypePreview
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

