// Ref: #/components/schemas/ProtocolDto
type ProtocolDto string

const (
	ProtocolDtoHTTP ProtocolDto = "http"
	ProtocolDtoTCP  ProtocolDto = "tcp"
)

// AllValues returns all ProtocolDto values.
func (ProtocolDto) AllValues() []ProtocolDto {
	return []ProtocolDto{
		ProtocolDtoHTTP,
		ProtocolDtoTCP,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s ProtocolDto) MarshalText() ([]byte, error) {
	switch s {
	case ProtocolDtoHTTP:
		return []byte(s), nil
	case ProtocolDtoTCP:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *ProtocolDto) UnmarshalText(data []byte) error {
	switch ProtocolDto(data) {
	case ProtocolDtoHTTP:
		*s = ProtocolDtoHTTP
		return nil
	case ProtocolDtoTCP:
		*s = ProtocolDtoTCP
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

